func:
// CONFIG: the only node to edit. It runs on every trigger.
// In: any message from an inject node. Out: the same message.
// The settings are stored in flow context (flow.get('cfg')).
var cfg = {
  // Output path in the data lake. The file is replaced on every run.
  path: 'mufti_test/ref_target_seed/ref_target_seed.parquet',
  // true = log row counts and first rows, write NO file. false = write.
  dryRun: true,
  // Technical user. Fill in after import. Do not share the flow filled in.
  tenantName: 'reckitt',
  clientId: 'PUT_CLIENT_ID_HERE',
  clientSecret: 'PUT_CLIENT_SECRET_HERE',
  gateway: 'https://gateway.eu1.mindsphere.io',
  // Assets to read. An empty list = every configured OEE asset except the
  // excluded ones below.
  assetIds: [
    // B2 Line (Hull)
    'cf4565d7da1e4efcbc0ea6a4814b8eee',
    // GT4 (Hull)
    'bc08dae161124f1cb533199f556190b3'
  ],
  // Skip any asset with one of these names.
  excludeNames: [],

  // Only dim_asset: skip any asset below an asset with one of these names.
  excludeAncestorNames: ['Test Line']
};
flow.set('cfg', cfg);
node.status({
  fill: cfg.dryRun ? 'yellow' : 'green',
  shape: 'dot',
  text: cfg.dryRun ? 'DRY RUN' : 'WRITE MODE'
});
return msg;

// Starts one run. In: any message from CONFIG (inject or test start).
// Out: msg.payload = the run day text YYYY-MM-DD, and msg.mode.
// A start like {start: 'YYYY-MM-DD'} fixes the day, otherwise it is today.
var day = new Date().toISOString().slice(0, 10);
var start = msg.payload;
if (start && typeof start === 'object' && start.start) {
  day = start.start;
}
msg.payload = day;
msg.mode = 'reference';
return msg;

// Builds the token request. The next node is an http request node.
// In: a day message {payload: 'YYYY-MM-DD', mode}.
// Out: msg.method, msg.url and msg.headers for the token POST.
var cfg = flow.get('cfg');
var credentials = cfg.clientId + ':' + cfg.clientSecret;
msg.day = msg.payload;
msg.loadedAt = Date.now();
msg.method = 'POST';
msg.url = 'https://' + cfg.tenantName +
  '.piam.eu1.mindsphere.io/oauth/token?grant_type=client_credentials';
msg.headers = {
  'Authorization': 'Basic ' + Buffer.from(credentials).toString('base64'),
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Keeps the token and builds the OEE asset list request (isConfigured,
// isManual). In: the token response. Out 1: the request for the http node.
// Out 2: a log message when the token request failed.
var cfg = flow.get('cfg');
var token = msg.payload && msg.payload.access_token;

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !token) {
  var failed = 'FAILED, NOTHING WRITTEN: token request failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}
msg.token = token;
msg.method = 'GET';
msg.url = cfg.gateway + '/api/oee/v3/assets';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return [msg, null];

// Chooses the assets to read for a reference table.
// In: the OEE asset list. Out 1: msg.payload = [{id, name, isManual,
// isConfigured, reasonTreeId}] for the next node. Out 2: a log message.
var KEEP_UNCONFIGURED = false;
var cfg = flow.get('cfg');
var byId = {};
var skipped = [];
var targets = [];

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
  var failed = 'FAILED, NOTHING WRITTEN: OEE asset list failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}

msg.payload.forEach(function (o) {
  byId[o.assetId] = o;
});
var ids = cfg.assetIds;
if (!ids || !ids.length) {
  ids = msg.payload.map(function (o) {
    return o.assetId;
  });
}
ids.forEach(function (id) {
  var o = byId[id];
  if (!o) {
    skipped.push(String(id).slice(0, 6) + '... not an OEE asset');
    return;
  }
  if (cfg.excludeNames.indexOf(o.name) >= 0) {
    skipped.push(o.name + ' excluded');
    return;
  }
  if (o.isConfigured === false && !KEEP_UNCONFIGURED) {
    skipped.push(o.name + ' not configured');
    return;
  }
  targets.push({
    id: id,
    name: o.name,
    isManual: o.isManual,
    isConfigured: o.isConfigured !== false,
    reasonTreeId: o.reasonTreeId || null
  });
});
msg.planSkipped = skipped;

if (!targets.length) {
  var nothing = 'NOTHING TO WRITE (no assets to read)';
  if (skipped.length) {
    nothing += ' | skipped: ' + skipped.join('; ');
  }
  return [null, logMessage(nothing)];
}
msg.payload = targets;
node.status({
  fill: 'blue',
  shape: 'dot',
  text: targets.length + ' asset(s)'
});
return [msg, null];

// Builds the OEE request for the KPI targets (thresholds) of one asset.
// In: one asset {id, name, ...} from the split node.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
msg.asset = msg.payload;
msg.method = 'GET';
msg.url = cfg.gateway + '/api/oee/v3/assets/' +
  encodeURIComponent(msg.asset.id);
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Builds the ref_target_seed rows (one per KPI) of one asset.
// In: the OEE asset response with thresholds. Out: msg.payload = an item
// {name, failed, skipped, rows} for the join. is_set = a value above 0.
var KPI_NAMES = [
  'OEE',
  'Availability',
  'Performance',
  'Quality'
];
var asset = msg.asset;
var body = msg.payload || {};
var item = {
  name: asset.name,
  failed: null,
  skipped: null,
  rows: []
};

function valueOf(list, kpi) {
  var found = null;
  (list || []).forEach(function (entry) {
    if (entry.name === kpi && typeof entry.value === 'number') {
      found = entry.value;
    }
  });
  return found;
}

if (msg.statusCode !== 200 || !body.thresholds) {
  var text = asset.name + ': thresholds failed, HTTP ';
  item.failed = text + msg.statusCode;
  msg.payload = item;
  return msg;
}

KPI_NAMES.forEach(function (kpi) {
  var warning = valueOf(body.thresholds.warnings, kpi);
  var error = valueOf(body.thresholds.errors, kpi);
  item.rows.push({
    asset_id: asset.id,
    asset_name: asset.name,
    kpi: kpi,
    warning: warning,
    error: error,
    is_set: warning > 0 || error > 0,
    loaded_at: msg.loadedAt
  });
});
msg.payload = item;
return msg;

// Collects the items that the join delivered into one list of rows.
// In: msg.payload = array of items {name, failed, skipped, rows}.
// Out: msg.rows, msg.failed and msg.skipped (lists), msg.itemCount.
var items = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
var rows = [];
var failed = [];
var skipped = (msg.planSkipped || []).slice();

items.forEach(function (item) {
  if (!item) {
    return;
  }
  if (item.failed) {
    failed.push(item.failed);
  }
  if (item.skipped) {
    skipped.push(item.skipped);
  }
  rows = rows.concat(item.rows || []);
});
msg.rows = rows;
msg.failed = failed;
msg.skipped = skipped;
msg.itemCount = items.length;
delete msg.payload;
return msg;

// Decides what happens with the table ref_target_seed.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = 'ref_target_seed ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.path;
msg.filename = msg.path.split('/').pop();
return msg;
